    ["snmp_ratio_descr"] = "Le Ratio Débit/SNMP est calculé en divisant le trafic total de l'interface obtenu à l'aide des flux, par le trafic total de la même interface lu via SNMP. Comme dans l'analyse basée sur les flux, les en-têtes non IP et de couche 2 ne sont pas pris en compte, les valeurs de rapport typiques sont comprises entre 0,8 et 0,9 (c'est-à-dire que 0,9 signifie que 90 % % du trafic reçu observé via SNMP a été signalé dans les flux) .<br>Le ratio est calculé en utilisant le trafic des 5 dernières minutes, car des parcours SNMP périodiques sont effectués à intervalles de 5 minutes. Le ratio n'est calculé que lorsque les conditions suivantes sont remplies",
