    ["note_drop_ifstats_dynamic"] = "Les drops sont disponibles dans l'interface principale",
    ["note_drops_sflow"] = "Les abandons sont affichés uniquement pour sFlow, car NetFlow ne les signale pas.<br><A HREF=https://www.ietf.org/rfc/rfc3176.txt>sFlow</A> les abandons comptent le nombre de fois où l'agent sFlow a détecté qu'un paquet marqué pour être échantillonné a été abandonné en raison d'un manque de ressources. Le compteur de chutes indique le nombre total de chutes détectées depuis la dernière réinitialisation de l'agent. Un taux d'abandon élevé indique que l'agent de gestion est incapable de traiter les échantillons aussi rapidement qu'ils sont générés par le matériel. L'augmentation du taux d'échantillonnage sFlow réduira le taux d'abandon. Remarque : Un agent qui ne peut pas détecter les chutes rapportera toujours zéro.",
    ["note_lifetime_timeout"] = "Quelle que soit la durée du flux, un flux qui a été actif pendant plus que la durée de vie maximale spécifiée <A HREF=https://www.ntop.org/guides/nprobe/cli_options.html?highlight=maximum%20flow%20lifetime>lifetime</A> est considéré comme expiré et sera émis (option nProbe -t)",
    ["note_packets"] = "Dans les réseaux Ethernet, chaque paquet a un <A HREF=\"https://en.wikipedia.org/wiki/Ethernet_frame\">overhead de 24 octets</A> [préambule (7 octets), début de trame (1 octet), CRC (4 octets) et <A HREF=\"http://en.wikipedia.org/wiki/Interframe_gap\">IFG</A> (12 octets)]. Cette surcharge doit être prise en compte dans le trafic d'interface, mais elle n'est pas ajoutée au trafic échangé entre les adresses IP. En effet, ces données contribuent à la charge de l'interface, mais elles ne peuvent pas être prises en compte dans le trafic échangé par les hôtes et ne s'attendent donc qu'à de faibles écarts entre les valeurs du trafic de l'hôte et de l'interface.",
    ["note_probe_zmq_drops_export_queue_full"] = "La sonde distante a traité avec succès ces flux, mais n'a pas pu les mettre en file d'attente pour l'exportation car la file d'attente d'exportation était pleine.",
    ["note_probe_zmq_drops_flow_collection_drops"] = "Nombre total de flux abandonnés dus du côté de nProbe (par exemple en raison d'abandons de collecte ou d'exportation)",
    ["note_probe_zmq_drops_flow_collection_udp_socket_drops"] = "Paquets de flux abandonnés sur le socket de collecte nProbe",
    ["note_probe_zmq_timeout_lifetime"] = "Durée de vie du flux telle qu'annoncée par nProbe et durée de vie réelle calculée sur les flux collectés",
    ["note_remote_probe_time"] = "Différence en secondes entre l'heure ntopng et l'heure nProbe distante : idéalement, elle devrait être proche de zéro. S'il est trop grand, veuillez synchroniser l'heure nProbe/ntopng",
