    ["duration"] = "Durée",
    ["dynamic_interfaces_creation_description"] = "ntopng peut utiliser un critère pour désagréger le trafic entrant. Lorsqu'un critère de désagrégation est sélectionné, ntopng utilisera la valeur du critère pour détourner le trafic entrant vers des interfaces créées dynamiquement. Par exemple, lorsque le critère « VLAN Id » est sélectionné, une interface dynamique sera créée pour chaque VLAN Id observé, et le trafic entrant sera détourné vers une interface dynamique en fonction de la valeur VLAN Id.",
    ["dynamic_interfaces_creation_note_0"] = "La désagrégation « VLAN Id » est prise en charge à la fois pour les interfaces physiques et pour les flux reçus via ZMQ. Les autres critères de désagrégation ne sont pris en charge que pour les flux ZMQ et seront inefficaces pour les interfaces physiques.",
    ["dynamic_interfaces_creation_note_1"] = "Les changements de critères n’affecteront pas les interfaces existantes. <b>Un redémarrage de ntopng est requis pour que la modification prenne effet</b>.",
    ["dynamic_interfaces_creation_note_2"] = "Lors de l'utilisation du critère « Interface d'entrée » sur des sondes non-sflow, %%INPUT_SNMP doit apparaître dans le modèle nprobe.",
    ["dynamic_interfaces_creation_note_3"] = "Le critère de désagrégation « Interface » ajoute tout flux à deux interfaces dynamiques. La valeur de %%INPUT_SNMP est utilisée pour sélectionner la première interface dynamique, tandis que la valeur de %%OUTPUT_SNMP est utilisée pour sélectionner la seconde.",
    ["dynamic_interfaces_creation_note_4"] = "Une désagrégation personnalisée du trafic au moyen de filtres de type BPF est également disponible en désactivant la désagrégation dynamique du trafic (réglez-la sur « Aucune ») via l'onglet Désagrégation personnalisée du trafic.",
    ["dynamic_interfaces_creation_title"] = "Désagrégation dynamique du trafic",
