    ["toggle_dump_duplicated_flows_to_clickhouse_description"] = "Videz les flux dupliqués dans ClickHouse. Par défaut, les flux dupliqués sont ignorés et comptabilisés uniquement comme dupliqués (pour éviter de casser les compteurs).",
    ["toggle_dump_duplicated_flows_to_clickhouse_title"] = "Vider les flux dupliqués",
