    ["toggle_elasticsearch_notification_title"] = "Toggle Notification Elasticsearch",
    ["toggle_elephant_flows_alerts_description"] = "Activer/désactiver les alertes générées lorsqu'un flux d'éléphants a été détecté. Ceci est utile pour détecter les comportements indésirables (par exemple l’exfiltration de données).",
