    ["toggle_emit_flow_alerts_description"] = "Vous pouvez désactiver la génération d'alertes de flux afin d'économiser des cycles CPU. Dans ce cas, le score sera mis à jour mais aucune alerte de flux ne sera déclenchée.",
    ["toggle_emit_flow_alerts_title"] = "Émettre des alertes de flux",
