    ["toggle_emit_host_alerts_title"] = "Émettre des alertes d'hôte",
    ["toggle_enable_automatic_reports_descr"] = "Basculez la génération de rapports périodiques (quotidiens). Les rapports sont générés pour toutes les interfaces et peuvent être désactivés individuellement dans la page des paramètres de l'interface.",
