    ["toggle_exporters_ndpi_ts_creation_title"] = "Application Flow Exporters L7",
    ["toggle_external_auth_captive_portal_description"] = "Authentifiez et autorisez l'utilisateur à l'aide d'un service externe exécuté sur l'URL de la page informative. Le service externe doit ajouter l'appareil, qui n'est pas attribué par défaut, à l'utilisateur nEdge approprié pour l'autoriser.",
    ["toggle_external_auth_captive_portal_title"] = "Authentification/Autorisation externe",
    ["toggle_fingerprint_stats_description"] = "Basculer les statistiques d'empreintes digitales de l'hôte",
    ["toggle_fingerprint_stats_title"] = "Statistiques d'empreintes digitales",
    ["toggle_flow_aggregated_alerted_flows_description"] = "Incluez tous les flux alertés dans les flux agrégés.",
    ["toggle_flow_aggregated_alerted_flows_title"] = "Inclure les flux alertés",
    ["toggle_flow_aggregated_limit_description"] = "Nombre maximal d'entrées de flux agrégées à insérer pour chaque vidage horaire.",
    ["toggle_flow_aggregated_limit_title"] = "ClickHouse limite les flux agrégés",
