    ["toggle_flow_aggregated_traffic_limit_title"] = "Trafic de flux agrégé minimum ClickHouse",
    ["toggle_flow_rrds_description"] = "Activez/désactivez la création de séries temporelles d'octets pour chaque port du périphérique d'exportation de flux distant tel que reçu via ZMQ (par exemple, sFlow/NetFlow/SNMP).<br>Pour les sondes non sFlow, %%INPUT_SNMP et %%OUTPUT_SNMP doivent apparaître dans le modèle nprobe.",
    ["toggle_flow_rrds_resolution_description"] = "Ceci indique la fréquence des mises à jour pour chaque série temporelle Flow Exporter / nProbe",
