    ["toggle_host_mask_description"] = "Pour des raisons de confidentialité, il peut être nécessaire de masquer les adresses IP des hôtes. Par exemple, si vous êtes un FAI, vous n'êtes pas censé savoir quelles adresses locales accèdent aux hôtes distants.",
    ["toggle_host_mask_title"] = "Masquer les adresses IP des hôtes",
    ["toggle_host_pools_log_description"] = "Activez/désactivez la création de journaux liés aux pools d'hôtes. Les journaux incluent les associations et dissociations d'hôtes à leurs pools d'hôtes.",
    ["toggle_host_pools_log_title"] = "Activer le journal des événements du pool d'hôtes",
    ["toggle_host_tskey_description"] = "Clé à utiliser pour le vidage des données et des séries temporelles pour les hôtes du domaine de diffusion local. Dans un réseau DHCP, il est généralement conseillé de choisir « Adresse MAC ».",
    ["toggle_host_tskey_title"] = "Identifiant des hôtes du domaine de diffusion local",
    ["toggle_http_auth"] = "Basculer l'authentification HTTP",
    ["toggle_http_auth_descr"] = "Basculez l’authentification graphique via un authentificateur HTTP.",
    ["toggle_ids_alert_description"] = "Activer/désactiver les alertes générées par les systèmes de détection d'intrusion. Découvrez l'intégration de Suricata via syslog.",
    ["toggle_ids_alert_title"] = "Alertes IDS",
    ["toggle_informative_captive_portal_description"] = "N'authentifiez pas les utilisateurs. Afficher uniquement une page informative avant de permettre aux utilisateurs d'accéder à Internet.",
    ["toggle_informative_captive_portal_title"] = "Informatif",
    ["toggle_interface_name_only_description"] = "Si activé, affichez le nom de l’interface uniquement dans le menu déroulant.",
    ["toggle_interface_name_only_title"] = "Nom de l'interface uniquement",
    ["toggle_internals_rrds_description"] = "Activez/désactivez la création de séries temporelles <a href=\"%{url}\">internes</a>, par exemple, les entrées des tables de hachage, la durée des activités périodiques et le nombre de points de séries temporelles écrits, la durée des scripts et le nombre d'appels.",
    ["toggle_internals_rrds_title"] = "Internes",
    ["toggle_intranet_traffic_rrds_description"] = "Activez/désactivez la création de séries temporelles de trafic entre les réseaux.<br><b>Remarque :</b> Ces séries temporelles ne seront disponibles que si les séries temporelles du réseau local sont activées et elles peuvent être trouvées sous l'onglet Séries temporelles du réseau (par exemple, 192.168. 2.1/24 -> 172.10.1.1/24).",
    ["toggle_intranet_traffic_rrds_title"] = "Matrice de trafic réseau",
    ["toggle_ldap_anonymous_bind_description"] = "Activez la liaison anonyme.",
    ["toggle_ldap_anonymous_bind_title"] = "Liaison anonyme LDAP",
    ["toggle_ldap_auth"] = "Toggle Authentification LDAP",
    ["toggle_ldap_auth_descr"] = "Basculer l'authentification graphique via LDAP.",
    ["toggle_ldap_debug_description"] = "Activez le débogage de l'authentification LDAP. Des informations supplémentaires sont imprimées dans les journaux ntopng.",
    ["toggle_ldap_debug_title"] = "Débogage LDAP",
    ["toggle_ldap_ext_user_cap_description"] = "Activer des fonctionnalités supplémentaires pour les utilisateurs LDAP qui ne sont pas des administrateurs (par exemple, accès au flux historique)",
    ["toggle_ldap_ext_user_cap_title"] = "Activer les fonctionnalités des utilisateurs étendus",
    ["toggle_ldap_referrals_description"] = "Spécifie si le client doit suivre automatiquement les références renvoyées par les serveurs LDAP.",
    ["toggle_ldap_referrals_title"] = "Suivre les références",
    ["toggle_local_auth"] = "Activer/désactiver l'authentification locale",
    ["toggle_local_auth_descr"] = "Basculez l'authentification graphique en fonction des utilisateurs définis par %{product}.",
    ["toggle_local_host_cache_enabled_description"] = "Activez/désactivez la création d'entrées de cache pour les hôtes locaux inactifs. Les compteurs d'hôtes locaux mis en cache sont automatiquement restaurés à leurs valeurs précédentes lors de la détection d'un trafic hôte supplémentaire.",
    ["toggle_local_host_cache_enabled_title"] = "Cache des hôtes locaux inactifs",
    ["toggle_local_hosts_one_way_ts_description"] = "Activez/désactivez la création de séries temporelles pour le trafic à sens unique. Le trafic unidirectionnel est souvent généré par des hôtes distants effectuant des sondages, il est donc conseillé de laisser cette option désactivée.",
    ["toggle_local_hosts_one_way_ts_title"] = "Série chronologique de trafic à sens unique",
    ["toggle_local_hosts_ts_creation_description"] = "Activez la création complète de séries temporelles d'hôtes (complète), limitez-la aux octets et au score (léger) ou désactivez-la.",
    ["toggle_local_hosts_ts_creation_title"] = "Héberger des séries temporelles",
    ["toggle_log_to_file_description"] = "Activez/désactivez la création de ntopng.log dans le répertoire de vidage des données au lieu d'utiliser syslog. Les paramètres prendront effet au prochain démarrage de %{product}.",
    ["toggle_log_to_file_title"] = "Activer le journal de suivi",
    ["toggle_logging_level_description"] = "Choisissez le niveau de journalisation d'exécution.",
    ["toggle_logging_level_title"] = "Niveau de journalisation",
    ["toggle_longlived_flows_alerts_description"] = "Activer/désactiver les alertes générées lorsqu'un flux de longue durée a été détecté. Ceci est utile pour détecter les comportements indésirables (par exemple l’exfiltration de données).",
    ["toggle_longlived_flows_alerts_title"] = "Alertes de flux à longue durée de vie",
    ["toggle_mdns_repeater_description"] = "Transférez les demandes/réponses MDNS (multicast) entre les interfaces LAN, même avec des sous-réseaux différents.",
    ["toggle_mdns_repeater_title"] = "Transfert MDNS",
