    ["toggle_menu_entry_help_title"] = "Entrée du menu Aide",
    ["toggle_message_broker_description"] = "Activer l'envoi de statistiques et d'informations à un courtier de messages.",
    ["toggle_message_broker_title"] = "Activer le courtier",
    ["toggle_midnight_stats_reset_description"] = "Activez la réinitialisation automatique des statistiques à minuit. Cela inclut les statistiques des hôtes et des adresses MAC.",
    ["toggle_midnight_stats_reset_title"] = "Réinitialisation des statistiques de minuit",
    ["toggle_mysql_check_open_files_limit_description"] = "Activez les générations d'alertes MySQL en raison des vérifications périodiques de MySQL open_files_limit.<br>La vérification open_files_limit est utile pour détecter lorsque le nombre de fichiers MySQL ouverts est élevé, ce qui pourrait entraîner des erreurs d'insertion dans la base de données.",
    ["toggle_mysql_check_open_files_limit_title"] = "Activer les alertes MySQL",
