    ["toggle_ndpi_flows_rrds_title"] = "Flux totaux de couche 7",
    ["toggle_ndpi_timeseries_creation_description"] = "Activez/désactivez la création de séries temporelles d'application de couche 7. La création d'une série temporelle par application nécessite plus d'espace disque et des E/S supplémentaires et, en général, ce n'est pas nécessaire.",
    ["toggle_ndpi_timeseries_creation_title"] = "Applications de couche 7",
    ["toggle_netbox_description"] = "Activer/Désactiver l'intégration de NetBox",
    ["toggle_netbox_title"] = "NetBox",
    ["toggle_network_discovery_debug_description"] = "Activez le débogage de Network Discovery. L'activation de cette option imprimera des informations supplémentaires dans les journaux ntopng.",
    ["toggle_network_discovery_debug_title"] = "Débogage de la découverte du réseau",
    ["toggle_network_discovery_description"] = "Activez/désactivez la découverte périodique des périphériques réseau à l'aide de plusieurs techniques, notamment l'analyse ARP, MDNS et SSDP.<p><b><b>REMARQUE</b> :</b> la découverte peut être <u>uniquement</u> activée. sur des interfaces physiques (c'est-à-dire pas de ZMQ) où nous pouvons envoyer/recevoir du trafic vers le réseau (c'est-à-dire que les interfaces en lecture seule telles que celles connectées aux miroirs de ports ne fonctionneront pas).",
    ["toggle_network_discovery_title"] = "Découverte active du réseau",
    ["toggle_ntopng_assets_inventory_description"] = "Activer la base de données d'inventaire des actifs intégrée",
    ["toggle_ntopng_assets_inventory_title"] = "Inventaire des actifs intégré",
    ["toggle_observation_points_rrd_creation_description"] = "Activez/désactivez la création de séries temporelles d'octets et de flux pour les points d'observation disponibles.",
    ["toggle_observation_points_rrds_description"] = "Basculez la série temporelle des points d’observation. Aucune série temporelle n'est créée s'il n'y a pas de points d'observation.<br><b>Remarque :</b> Les préférences des applications L7 des séries temporelles d'Observation Point sont les mêmes que celles de l'interface ; Ainsi, si aucune série temporelle n'est créée pour les applications d'interface L7, aucune série temporelle n'est créée pour les applications Observation Points L7.",
    ["toggle_observation_points_rrds_title"] = "Points d'observation",
    ["toggle_oidc_auth"] = "Toggle Authentification OIDC",
    ["toggle_oidc_auth_descr"] = "Activez l'authentification unique via un fournisseur d'identité OpenID Connect (Keycloak, Okta, Azure AD, Google, etc.).",
    ["toggle_oidc_auto_create_users_description"] = "Créez automatiquement un compte ntopng lors de la première connexion OIDC. Lorsqu'il est désactivé, l'utilisateur doit être pré-créé manuellement.",
    ["toggle_oidc_auto_create_users_title"] = "Créer automatiquement des utilisateurs",
    ["toggle_pools_rrds_description"] = "Activez/désactivez la création de séries temporelles d'octets et d'applications pour les pools d'hôtes définis.",
    ["toggle_pools_rrds_title"] = "Pools d'hôtes",
    ["toggle_query_performance_log_description"] = "Consigne le temps d'exécution des requêtes SQL sur les données historiques qui prennent plus d'une seconde.",
    ["toggle_query_performance_log_title"] = "Journal des performances des requêtes SQL",
    ["toggle_radius_accounting"] = "Activer/désactiver la comptabilité RADIUS",
    ["toggle_radius_accounting_descr"] = "Basculez la comptabilité du trafic via le serveur RADIUS.",
    ["toggle_radius_auth"] = "Toggle Authentification RADIUS",
    ["toggle_radius_auth_descr"] = "Basculez l’authentification GUI via le serveur RADIUS.",
    ["toggle_radius_external_auth_for_local_users"] = "Toggle Authentification RADIUS des utilisateurs locaux",
    ["toggle_radius_external_auth_for_local_users_descr"] = "Basculez l'authentification des utilisateurs locaux via RADIUS (authentification à distance, autorisation locale).",
    ["toggle_search_in_all_interfaces_description"] = "Activez la recherche d'hôtes dans toutes les interfaces, pas seulement celle actuellement sélectionnée.",
    ["toggle_search_in_all_interfaces_title"] = "Rechercher dans toutes les interfaces",
    ["toggle_send_telemetry_data_description"] = "Contribuez au projet en envoyant des <a href=\"%{url}\">données de télémétrie anonymes</a> cryptées à <a href=\"%{ntop_org}\">ntop.org</a>. Les données impliquent uniquement l'état de %{product} (par exemple, disponibilité, état, rapports d'erreur). Rien concernant le trafic surveillé ne sera jamais envoyé.",
    ["toggle_send_telemetry_data_title"] = "Données de télémétrie",
    ["toggle_shaping_directions_description"] = "Activez cette option pour pouvoir définir différentes politiques de mise en forme pour le trafic d'entrée et de sortie.",
    ["toggle_shaping_directions_title"] = "Instructions de mise en forme divisées",
    ["toggle_sites_collection_description"] = "Créer une base de données des domaines visités à des fins de classification (stockés sur redis ntopng.domains)",
    ["toggle_sites_collection_title"] = "Collection de sites",
    ["toggle_skip_dpi_for_collected_flows"] = "Ignorer le DPI local pour les flux collectés",
    ["toggle_skip_dpi_for_collected_flows_description"] = "Ignorez le traitement DPI local pour les flux collectés à partir de sondes distantes (par exemple via ZMQ), car ils incluent déjà des informations de protocole. Comme inconvénient, certaines vérifications comportementales locales ne sont pas effectuées.",
    ["toggle_slack_notification_description"] = "Activez les notifications d'alertes via Slack. Consultez les instructions d'intégration <a href='%{url}'>ici</a>.",
    ["toggle_slack_notification_title"] = "Activer/désactiver la notification <a href=\"%{url}\">Slack</a>",
    ["toggle_snmp_alerts_port_duplexstatus_change_description"] = "Activer/désactiver les alertes générées lorsqu'un statut duplex d'interface change",
    ["toggle_snmp_alerts_port_duplexstatus_change_title"] = "Alertes de changement d'état du duplex de l'interface",
    ["toggle_snmp_alerts_port_errors_description"] = "Activer/désactiver les alertes générées lorsque les compteurs de rejets ou d'erreurs sur une interface augmentent",
    ["toggle_snmp_alerts_port_errors_title"] = "Alertes de rejets/erreurs d’interface",
    ["toggle_snmp_alerts_port_status_change_description"] = "Activer/désactiver les alertes générées lorsqu'un état opérationnel d'une interface change",
    ["toggle_snmp_alerts_port_status_change_title"] = "Alertes de changement d’état opérationnel de l’interface",
    ["toggle_snmp_debug_description"] = "Activez le débogage des périphériques SNMP. L'activation de cette option imprimera des informations supplémentaires dans les journaux ntopng.",
    ["toggle_snmp_debug_title"] = "Débogage SNMP",
    ["toggle_snmp_excluded_from_usage_description"] = "Par défaut, toutes les nouvelles interfaces/appareils seront ajoutés dans la page d'utilisation. En activant cette préférence à la place, toutes les nouvelles interfaces/périphériques seront exclus de cette page et pour les réinclure, la configuration de l'interface SNMP doit être modifiée.",
    ["toggle_snmp_excluded_from_usage_title"] = "Exclure les nouvelles interfaces de l'utilisation de SNMP",
    ["toggle_snmp_polling_description"] = "Activez/désactivez l'interrogation des périphériques SNMP.",
    ["toggle_snmp_polling_title"] = "Interrogation SNMP",
    ["toggle_snmp_port_admin_status_description"] = "Basculer le statut d'administrateur de l'interface. Le basculement est immédiat mais l'état réel affiché est actualisé lors du prochain sondage.",
    ["toggle_snmp_port_admin_status_title"] = "Statut d'administrateur de l'interface",
    ["toggle_snmp_port_qos_mib_polling_description"] = "Basculez l’interrogation QoS MIB d’une interface de périphérique.",
    ["toggle_snmp_port_qos_mib_polling_title"] = "Interrogation MIB QoS de l'interface",
    ["toggle_snmp_rrds_description"] = "Activez/désactivez la création de séries temporelles d'octets pour chaque port des périphériques SNMP. Pour chaque port de périphérique, une série temporelle avec des octets d'entrée/de sortie sera créée.",
    ["toggle_snmp_rrds_title"] = "Séries temporelles des périphériques SNMP",
    ["toggle_snmp_trap_description"] = "Activez la collecte d'interruptions SNMP sur le port UDP : 162.",
    ["toggle_snmp_trap_title"] = "Collecte d'interruptions SNMP",
    ["toggle_split_ts_direction_description"] = "Basculez entre l’affichage d’une seule série temporelle de trafic total (RX + TX) et de séries temporelles distinctes pour RX et TX. Lorsque l'option « Total » est sélectionnée (par défaut), une série temporelle combinée est générée. Sinon, des séries temporelles distinctes sont créées pour chaque direction (RX et TX).",
    ["toggle_split_ts_direction_title"] = "Instructions pour les séries temporelles fractionnées",
    ["toggle_src_with_post_nat_src_description"] = "Remplacez les adresses source IPv4 (%%IPV4_SRC_ADDR) et les ports (%%L4_SRC_PORT) par leurs valeurs post-nat (%%POST_NAT_SRC_IPV4_ADDR et %%POST_NAT_SRC_TRANSPORT_PORT).",
    ["toggle_src_with_post_nat_src_title"] = "Utiliser des adresses et des ports IPv4 sources post-nat",
    ["toggle_system_probes_timeseries_description"] = "Activez/désactivez la création de séries temporelles pour les sondes système telles que Active Monitoring et le moniteur Redis.",
    ["toggle_system_probes_timeseries_title"] = "Sondes",
    ["toggle_theme_description"] = "Basculer entre les thèmes.",
    ["toggle_theme_title"] = "Thème",
    ["toggle_thpt_content_description"] = "Sélectionnez l'unité de débit à afficher dans les rapports de trafic.",
    ["toggle_thpt_content_title"] = "Unité de débit",
    ["toggle_tiny_flows_dump_description"] = "Activez/désactivez le vidage des flux minuscules, c'est-à-dire des flux contenant peu de paquets ou d'octets. Réduit la cardinalité des flux dans les bases de données, accélère les insertions et les recherches. Le réglage de petits flux peut aider à limiter la cardinalité des flux sans réduire la visibilité sur les informations transférées.",
    ["toggle_tiny_flows_dump_title"] = "Décharge de petits flux",
    ["toggle_tls_quic_hostnaming_description"] = "Utilisez le TLS/QUIC SNI demandé comme nom d'hôte. L'activer rend la dénomination d'hôte plus efficace, mais cela peut introduire des faux positifs dans les noms d'hôte.",
    ["toggle_tls_quic_hostnaming_title"] = "Noms d'hôtes TLS et QUIC",
    ["toggle_toggle_starttls_description"] = "Activez l'utilisation de STARTTLS lorsque vous essayez de vous connecter au serveur de messagerie.",
    ["toggle_toggle_starttls_title"] = "Activer STARTTLS",
    ["toggle_top_sites_description"] = "Activez/désactivez la création des sites Web les plus visités pour les hôtes locaux. Les principaux sites sont créés à l'aide d'une <a href=\"%{url}\">heuristique</a> qui ne gère pas plus de 20 sites par hôte local. L'heuristique fonctionne entièrement en mémoire et ne nécessite aucune interaction avec le disque. Les meilleurs sites sont effacés toutes les 5 minutes. Une archive historique des sites Web les plus visités peut être créée, pour chaque hôte local, en interrogeant périodiquement le lien de téléchargement JSON <i class=\"fas fa-download fa-sm\"></i> accessible depuis la page de détails de l'hôte. Les protocoles d'application de ces sites sont : TLS, QUIC, HTTP et DNS",
    ["toggle_top_sites_title"] = "Sites les plus visités",
